describeLive('live Butlers project-shape discovery at the reviewed revision', () => {
  it('matches the independent five-root, seven-Heart, baseline and total populations', () => {
    const authority = evaluateBodyReadAuthority(loadBodyReadAuthorityInputs({
      repoRoot: SYZYGY_ROOT,
      governanceRevision: syzygyRevision(),
      evaluationId: 'evaluation:pwb-discovery-live-ec8b1f6',
      evaluationInstant: CAPTURED_AT,
    }));
    expect(authority.admits).toBe(true);
    const runGit = gitRunnerFor(BUTLERS_REPO as string);
    const detectors = compileDetectors(PWB_SECRET_POLICY);
    const observation = observeProjectShapeSources({
      repositoryId: PWB_REPOSITORY_ID,
      revision: BUTLERS_REVISION,
      capturedAt: CAPTURED_AT,
      runGit,
      authority,
      classifyPhaseA: (text) => classifyPhaseASeed(detectors, text),
    });
    expect(observation.kind).toBe('observed');
    if (observation.kind !== 'observed') return;
    expect(observation.revision).toBe(BUTLERS_REVISION);
    expect(observation.manifest.pillars.find((pillar) => pillar.key === 'spec-and-spine')).toMatchObject({ reason: 'index-missing-at-revision', indexPath: 'openspec/README.md' });
    expect(observation.manifest.pillars.map((pillar) => [pillar.key, pillar.state, pillar.root])).toEqual([
      ['heart-and-soul', 'discovered', 'about/heart-and-soul'],
      ['legends-and-lore', 'discovered', 'about/legends-and-lore'],
      // `openspec/` carries no README index at this revision (index-missing-at-revision).
      ['spec-and-spine', 'unknown', 'openspec'],
      // Discovered again at this head: the index no longer carries the active
      // content that excluded it at a3dd1fe.
      ['lay-and-land', 'discovered', 'about/lay-and-land'],
      ['craft-and-care', 'discovered', 'about/craft-and-care'],
    ]);
    expect({
      total: observation.sources.length,
      about: observation.sources.filter((source) => source.path.startsWith('about/')).length,
      baseline: observation.sources.filter((source) => /^openspec\/specs\/[^/]+\/spec\.md$/.test(source.path)).length,
      roster: observation.sources.filter((source) => /^roster\/[^/]+\/(?:butler\.toml|MANIFESTO\.md)$/.test(source.path)).length,
    }).toEqual({ total: 270, about: 59, baseline: 185, roster: 26 });
    expect(observation.sources.filter((source) => source.path.startsWith('about/heart-and-soul/')).map((source) => source.path)).toEqual([
      'about/heart-and-soul/README.md',
      'about/heart-and-soul/architecture.md',
      'about/heart-and-soul/design-language.md',
      'about/heart-and-soul/development.md',
      'about/heart-and-soul/security.md',
      'about/heart-and-soul/v1.md',
      'about/heart-and-soul/vision.md',
    ]);

    const shape = buildProjectShape({ authority, revision: BUTLERS_REVISION, capturedAt: CAPTURED_AT, runGit });
    expect(shape.kind).toBe('observed');
    if (shape.kind !== 'observed') return;
    expect(shape.counts.sources).toBe(270);
    expect(shape.counts.classification.classifiedByBasis).toEqual({ body: 74, 'path-only': 185 });
    expect(shape.counts.sourcesWithKnownItemDenominator).toBe(259);
    expect(shape.items.filter((item) => item.class === 'baseline-spec')).toHaveLength(185);
    expect(shape.classes['baseline-spec'].denominator).toEqual({ kind: 'known', value: 185 });
    expect(shape.sources.find((source) => source.path === 'about/heart-and-soul/vision.md')?.itemDenominator).toEqual({ kind: 'known', value: 15 });
    expect(shape.sources.find((source) => source.path === 'about/heart-and-soul/architecture.md')?.itemDenominator).toEqual({ kind: 'known', value: 1 });
    expect(shape.sources.find((source) => source.path === 'about/heart-and-soul/v1.md')?.itemDenominator).toMatchObject({
      kind: 'unknown',
      grammarFailure: { reason: 'ambiguous-leading-label', class: 'catalog-entry', line: 95 },
    });
    expect(shape.projectAccount.filter((entry) => entry.claim.epistemic.label === 'Observed')).toHaveLength(4);
    expect(shape.projectAccount.filter((entry) => entry.claim.epistemic.label === 'Unknown').map((entry) => entry.key)).toEqual(['v1-scope', 'v1-success']);
  });
})

describeLive('live real focused-pytest verification (SYZYGY_POC_BUTLERS_REPO gated)', () => {
  const repoRoot = BUTLERS_REPO as string;

  it('ingests one real, passing operator-reported focused-pytest artifact and resolves it to report-fact, never Verified, through the full model (AC1/AC3, RFC5-19)', () => {
    if (JUNIT === undefined || JUNIT_COMMIT === undefined || JUNIT_EXIT === undefined) {
      throw new Error(liveTestOperatorInstructions(repoRoot, PYTHON, SCOPE));
    }
    expect(JUNIT_EXIT, 'the operator-reported exit status (SYZYGY_POC_BUTLERS_JUNIT_EXIT)').toBe('0');

    const repositoryCommit = execFileSync('git', ['-C', repoRoot, 'rev-parse', 'HEAD'], {
      encoding: 'utf8',
    }).trim();
    // A run reported at one commit is never ingested against another.
    expect(repositoryCommit, 'HEAD at ingest against the operator-reported commit (SYZYGY_POC_BUTLERS_JUNIT_COMMIT)').toBe(JUNIT_COMMIT);

    const rawJUnit = readBoundedRegularFile(JUNIT);
    {
      // Refuses a status 0 beside failing, erroring or zero tests, and any
      // count that is not a non-negative integer.
      const built = buildOperatorReportedTestArtifactRecord({
        rawJUnit,
        command: [PYTHON, '-m', 'pytest', SCOPE, '-q'],
        reportedExitCode: Number(JUNIT_EXIT),
        ingestedAt: new Date().toISOString(),
        repositoryCommit,
        scope: SCOPE,
      });
      expect(built.kind, 'the operator-reported result file').toBe('built');
      if (built.kind !== 'built') throw new Error('unreachable');
      expect(built.record.provenance).toBe('operator-reported');
      expect(built.record.summary).toMatch(/passed/);
      expect(built.record.summary).not.toContain('Traceback');

      // Compose through the full shared model, with the git-based
      // worker-change observer's `runGit` seam pointed at this same real
      // commit — the observer's own commit-discovery logic is covered by
      // worker-change-observation.test.ts; this proves the *composition*
      // with a genuinely captured artifact end-to-end.
      const model = buildPocModel({
        seeds: BUTLERS_POC_SEEDS,
        repoRoot,
        repositoryRevision: repositoryCommit,
        observerRevision: repositoryCommit,
        evaluation: {
          snapshot: 'butlers@live-capture',
          asOf: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
        },
        materializationRecord: {
          beadId: 'bu-live-capture-1',
          externalRef: 'syzygy-poc:live-capture-test',
          targetRepoRoot: repoRoot,
          createdAt: new Date().toISOString(),
          doltRevisionAtCreation: null,
          attribution: 'live-test',
        },
        runWorkItemQuery: () =>
          JSON.stringify([
            {
              revision: 'dolt-live',
              id: 'bu-live-capture-1',
              title: 'live capture',
              status: 'in_progress',
              issue_type: 'task',
              priority: 1,
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString(),
              closed_at: null,
            },
          ]),
        runGit: (root, args) => {
          if (args[0] === 'symbolic-ref') return 'refs/remotes/origin/main';
          if (args[0] === 'rev-parse') return repositoryCommit;
          if (args[0] === 'log') {
            const format = `${repositoryCommit}\x1f${built.record.ingestedAt}\x1flive capture [bu-live-capture-1]`;
            return `${format}\n`;
          }
          if (args[0] === 'merge-base') return '';
          if (args[0] === 'for-each-ref') return 'main\n';
          return new TextDecoder('utf-8', { fatal: true }).decode(execFileSync('git', ['--no-optional-locks', '-C', root, ...args]));
        },
        testArtifactRecord: built.record,
      });

      expect(model.workerChange.kind).toBe('observed');
      if (model.workerChange.kind !== 'observed') throw new Error('unreachable');
      expect(model.workerChange.state).toBe('changed-or-merged');
      expect(model.testArtifactVerification).toEqual({
        kind: 'reported',
        tier: 'report-fact',
        record: built.record,
        disclosure: OPERATOR_REPORTED_DISCLOSURE,
      });
    }
  }, 120_000); // unmeasured: it runs only against an operator's real Butlers checkout (SYZYGY_POC_BUTLERS_REPO, 2c1f8d5a), which no hosted or local run sets; the commit holds no measurement, so this is an unmeasured residual of syzygy-bpyt.4.31
})

describeLive('live Butlers observation (SYZYGY_POC_BUTLERS_REPO gated)', () => {
  const repoRoot = BUTLERS_REPO as string;

  it('matches `git rev-parse HEAD` and a direct Dolt read (POC-REQ-001, POC-REQ-010 oracles)', () => {
    const expectedGitRevision = execFileSync('git', ['-C', repoRoot, 'rev-parse', 'HEAD'], {
      encoding: 'utf8',
    }).trim();
    const structure = observeCodeStructure({
      repoRoot,
      revision: expectedGitRevision,
      capturedAt: new Date().toISOString(),
    });
    expect(structure.kind).toBe('observed');
    if (structure.kind !== 'observed') throw new Error('unreachable');
    expect(structure.provenance.revision).toBe(expectedGitRevision);
    expect(structure.files.length).toBeGreaterThan(0);

    const workItems = observeWorkItems({
      repoRoot,
      beadPrefix: 'bu',
      capturedAt: new Date().toISOString(),
    });
    expect(workItems.kind).toBe('observed');
    if (workItems.kind !== 'observed') throw new Error('unreachable');

    const expectedRevision = execFileSync(
      'bd',
      ['--readonly', '--json', '-C', repoRoot, 'sql', "SELECT dolt_hashof('HEAD') AS revision"],
      { encoding: 'utf8' },
    );
    const expected = (JSON.parse(expectedRevision) as readonly { revision: string }[])[0];
    expect(workItems.provenance.revision).toBe(expected?.revision);
    expect(workItems.items.every((item) => item.id.startsWith('bu-'))).toBe(true);

    const sampled = workItems.items[0];
    expect(sampled).toBeDefined();
    const direct = execFileSync(
      'bd',
      [
        '--readonly',
        '--json',
        '-C',
        repoRoot,
        'sql',
        `SELECT status, created_at, updated_at FROM issues WHERE id = '${sampled?.id}'`,
      ],
      { encoding: 'utf8' },
    );
    const directRow = (
      JSON.parse(direct) as readonly { status: string; created_at: string; updated_at: string }[]
    )[0];
    expect(directRow?.status).toBe(sampled?.status);
    expect(directRow?.created_at).toBe(sampled?.createdAt);
  });
})

